package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen0Test {







    @Test
    public void testCreateNumber_Hexadecimal() {
        // Integer hex
        assertTrue(NumberUtils.createNumber("0x123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-0x123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("0X123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-0X123") instanceof Integer);

        // Long hex (more than 8 digits after 0x)
        assertTrue(NumberUtils.createNumber("0x123456789") instanceof Long);
        assertTrue(NumberUtils.createNumber("-0x123456789") instanceof Long);
    }












}

