package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen0Test {











    @Test
    public void testCreateNumber_FloatingPointTypes() {
        assertTrue(NumberUtils.createNumber("1.23") instanceof Float);
        assertTrue(NumberUtils.createNumber("1.23E2") instanceof Double);
        assertTrue(NumberUtils.createNumber("1.23e2") instanceof Double);
        assertTrue(NumberUtils.createNumber("1.23e") instanceof Number); // Logic handling for expPos

        // Testing precision fall-through (Large decimal that Float can't hold accurately)
        assertTrue(NumberUtils.createNumber("1.234567890123456789") instanceof BigDecimal);
    }








}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen0Test {













    @Test
    public void testCreateNumber_Suffixes() {
        // Long suffixes
        assertTrue(NumberUtils.createNumber("123L") instanceof Long);
        assertTrue(NumberUtils.createNumber("123l") instanceof Long);
        assertTrue(NumberUtils.createNumber("9223372036854775807L") instanceof Long);
        assertTrue(NumberUtils.createNumber("9223372036854775808L") instanceof BigInteger);

        // Float suffixes
        assertTrue(NumberUtils.createNumber("1.23F") instanceof Float);
        assertTrue(NumberUtils.createNumber("1.23f") instanceof Float);

        // Double suffixes
        assertTrue(NumberUtils.createNumber("1.23D") instanceof Double);
        assertTrue(NumberUtils.createNumber("1.23d") instanceof Double);

        // Invalid suffix
        try {
            NumberUtils.createNumber("123X");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            // Expected
        }
    }






}

