public class NumberUtils_createNumber_TriageGen0Test {

















    @Test
    public void testCreateNumber_EdgeCases() {
        // All zeros check
        assertTrue(NumberUtils.createNumber("0.000f") instanceof Float);
        assertTrue(NumberUtils.createNumber("0.000d") instanceof Double);

        // Test the specific error path: expPos < decPos
        try {
            NumberUtils.createNumber("1e.5"); 
            fail("Should throw NFE");
        } catch (NumberFormatException e) {}

        // Test the specific error path: expPos > length
        try {
            NumberUtils.createNumber("1.2e"); 
            // Note: The code logic for 'lastChar' being 'e' might trigger different paths
        } catch (NumberFormatException e) {}
    }


}

